code='''def transform(grid):
    from collections import deque
    g=[r[:] for r in grid]
    h,w=len(g),len(g[0])
    s=next((r,c) for r in range(h) for c in range(w) if g[r][c]==6)
    q=deque([s]); seen={s}
    while q:
        r,c=q.popleft()
        for dr,dc in ((-1,0),(1,0),(0,-1),(0,1)):
            n=(r+dr,c+dc)
            if 0<=n[0]<h and 0<=n[1]<w and n not in seen and g[n[0]][n[1]]!=1:
                seen.add(n);q.append(n)
    edge_blue=set()
    for r in range(h):
        for c in range(w):
            if g[r][c]==1:
                qq=deque([(r,c)]); obj={(r,c)}
                while qq:
                    a,b=qq.popleft()
                    for dr,dc in ((-1,0),(1,0),(0,-1),(0,1)):
                        n=(a+dr,b+dc)
                        if 0<=n[0]<h and 0<=n[1]<w and g[n[0]][n[1]]==1 and n not in obj:
                            obj.add(n);qq.append(n)
                if any(a in (0,h-1) or b in (0,w-1) for a,b in obj):edge_blue |= obj
    for r,c in seen:
        if g[r][c]==6:continue
        if r in (0,h-1) or c in (0,w-1) or any((r+dr,c+dc) in edge_blue for dr in (-1,0,1) for dc in (-1,0,1)):
            g[r][c]=7
    out=[row[:] for row in g]
    for r in range(h):
        for c in range(w):
            if grid[r][c]==1 and not any(0<=r+dr<h and 0<=c+dc<w and out[r+dr][c+dc]==7 for dr in (-1,0,1) for dc in (-1,0,1)):
                g[r][c]=8
    return g
'''
